"""Lighting information hosted in the existing communities page, without new URLs."""
SERVICE='Iluminación LED y sensores'
TARGET='/comunidades/#iluminacion-led'

def photo(small=False):
 css='local-product-thumb' if small else 'lighting-photo'
 return '<figure class="'+css+'"><img src="/assets/iluminacion-led.webp" alt="Plafón LED circular blanco con sensor integrado, imagen ilustrativa" width="960" height="720" loading="lazy" decoding="async"><figcaption>Imagen ilustrativa generada con IA.</figcaption></figure>'

def local_card():
 return '<article class="service-local" id="iluminacion-led" data-service-group="red"><h3>Iluminación LED y sensores</h3>'+photo(True)+'<p>Bombillas, plafones, focos, interruptores y pulsadores para viviendas, comunidades y escaparates.</p><a class="text-link" href="'+TARGET+'">Sensores, niveles de luz y alumbrado de emergencia</a><a class="text-link local-request" href="#contacto" data-service-choice="'+SERVICE+'">Consultar iluminación →</a></article>'

def directory_card():
 return '<article class="service-card"><a class="service-image lighting-card-image" href="'+TARGET+'" aria-label="Ver iluminación LED y sensores"><img src="/assets/iluminacion-led.webp" alt="Imagen ilustrativa de un plafón LED con sensor" width="960" height="720" loading="lazy"></a><div class="service-body"><p class="small">Imagen ilustrativa generada con IA.</p><span class="eyebrow">VIVIENDAS · COMUNIDADES · LOCALES</span><h3>Iluminación LED y sensores</h3><p>Cambio de bombillas y luminarias, plafones con detección y focos para escaparates.</p><a class="text-link" href="'+TARGET+'">Ver opciones de iluminación →</a></div></article>'

def guide():
 return '''<section class="section choice-section" id="iluminacion-led"><div class="wrap"><span class="eyebrow">ILUMINACIÓN · REVISADO 19 OCTUBRE 2026</span><h2>LED y encendido automático:<br>la luz que necesita cada espacio.</h2><p class="lead">Sustitución de bombillas, plafones y focos para pisos, portales, escaleras y locales. Revisamos luminaria, alimentación y control antes de elegir el recambio.</p>'''+photo()+'''<div class="choice-grid"><article class="choice-card"><h3>Bombillas y plafones LED</h3><p>Comprobación de casquillo o conexión, dimensiones, flujo luminoso, tono de luz y compatibilidad. Una bombilla sustituible y un plafón con LED integrado requieren soluciones diferentes; se valora si procede reparar el equipo o cambiar la luminaria.</p></article><article class="choice-card"><h3>Sensores de movimiento y crepusculares</h3><p>El detector de movimiento permite encender al paso; el crepuscular actúa según la luz ambiente. Se estudian ubicación, zona de detección, temporización y umbral de encendido para evitar zonas sin iluminar o activaciones innecesarias.</p></article><article class="choice-card"><h3>Interruptores y pulsadores</h3><p>Sustitución de mecanismos y revisión del encendido en viviendas o comunidades. Se identifica si el circuito utiliza interruptor, conmutación, pulsador o temporizador; no se cambia uno por otro solo porque encaje en el marco.</p></article></div><div class="article" style="margin-top:35px"><h3>Focos LED para escaparates</h3><p>Importan la orientación, el ángulo del haz, la reproducción de los colores y los reflejos en el cristal, además de la potencia. Para valorar una renovación, indica las dimensiones del escaparate, qué productos iluminas, altura disponible, equipos actuales y horario de uso. Una iluminación más intensa no siempre muestra mejor el producto.</p><h3>¿Cuántos lúmenes hacen falta según los metros cuadrados?</h3><p>Los lúmenes indican el flujo emitido por la luminaria; los lux expresan la luz que llega a una superficie. La elección considera uso del espacio, altura, distribución, óptica, colores de las superficies y mantenimiento. Los metros cuadrados ayudan a preparar el estudio, pero no bastan para elegir el número de plafones ni garantizan una iluminación uniforme. Se comprueba el resultado en las zonas de uso y paso.</p><h3>Alumbrado de emergencia: una función distinta</h3><p>Una luminaria normal con sensor no sustituye a un equipo de emergencia. Su selección y revisión consideran la función del espacio, recorridos, puntos que deben quedar visibles, autonomía y condiciones aplicables al edificio. Si un equipo no enciende cuando debe, se comprueban alimentación, batería y funcionamiento según su documentación; no se dimensiona únicamente por vatios o superficie.</p><h3>Luces que parpadean, no apagan o se quedan encendidas</h3><p>Indica si afecta a una luminaria o a todo el circuito y si empezó después de cambiar una bombilla, un sensor o un mecanismo. El diagnóstico puede requerir revisar alimentación, controlador LED, regulación y compatibilidad con el mando existente. No se atribuye siempre a la bombilla ni se promete resolverlo instalando un sensor nuevo.</p><h3>Control convencional o domótica Shelly</h3><p>Podemos estudiar encendido con mecanismos, detección u horarios. Si quieres control desde el móvil, consulta <a href="/servicios/domotica-shelly/">domótica Shelly</a>: se comprueban modelo, carga y funciones necesarias. No hace falta convertir cada luz a domótica para instalar LED o un detector.</p><h3>Qué enviar para preparar la propuesta</h3><p>Localidad, tipo de inmueble, espacios afectados, medidas aproximadas, número de puntos y fotos de las luminarias accesibles. En comunidades, añade quién autoriza la intervención y si se busca reparar o renovar. La propuesta debe precisar equipos, trabajos eléctricos, retirada de material, ajustes y comprobaciones. No abras cuadros ni mecanismos para obtener estos datos.</p><p class="small">Referencias: <a href="https://idae.es/tecnologias/eficiencia-energetica/edificacion/iluminacion-eficiente-en-edificios">IDAE · iluminación eficiente y sistemas de control</a> y <a href="https://www.codigotecnico.org/DocumentosCTE/SeguridadUtilizacionAccesibilidad.html">CTE DB-SUA · seguridad de utilización, sección SUA 4</a>. Los requisitos se verifican para el alcance concreto de la actuación.</p><a class="btn btn-primary" href="#contacto" data-service-choice="Iluminación LED y sensores">Consultar cambio de iluminación →</a></div></div></section>'''

def local_focus(name):
 from html import escape
 return '<section class="section local-spotlight" style="background:#f0e9e4"><div class="wrap content-columns"><div><span class="eyebrow">SI QUIERES RENOVAR LA ILUMINACIÓN</span><h2>LED y sensores<br>en '+escape(name)+'.</h2><p>Para un piso, portal o escaparate, indica qué zona necesita luz y qué quieres mejorar: sustituir una luminaria averiada, encender al paso o ajustar horarios. No se decide la solución solo por los vatios de la bombilla.</p><h3>El tipo de encendido cambia la propuesta</h3><p>Un plafón con detector, un sensor crepuscular y un pulsador con temporización cumplen funciones distintas. Se comprueban la zona de uso, la luz natural y el mando existente antes de proponer equipos.</p><a class="text-link" href="'+TARGET+'">Cómo elegir plafones, sensores y focos LED →</a></div><aside class="callout">'+photo()+'<h3>Prepara tu consulta de iluminación</h3><ul><li>Dimensiones y altura aproximadas del espacio.</li><li>Número de puntos y tipo de luminaria existente.</li><li>Si falla una luz o todo el circuito.</li><li>Si buscas alumbrado habitual o de emergencia.</li></ul><p>Los niveles de luz y las condiciones de emergencia se estudian por separado.</p><a class="text-link" href="#contacto" data-service-choice="'+SERVICE+'">Consultar iluminación en '+escape(name)+' →</a></aside></div></section>'
